  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ============================================================\n// USER & AUTHENTICATION\n// ============================================================\n\nenum UserRole {\n  PATIENT\n  DOCTOR\n  ADMIN\n}\n\nenum UserStatus {\n  ACTIVE\n  INACTIVE\n}\n\nmodel User {\n  id           String     @id @default(cuid())\n  email        String     @unique\n  passwordHash String\n  firstName    String\n  lastName     String\n  phone        String?\n  role         UserRole\n  status       UserStatus @default(ACTIVE)\n\n  patientProfile PatientProfile?\n  doctorProfile  DoctorProfile?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  notifications Notification[]\n\n  @@index([role])\n  @@index([status])\n}\n\n// ============================================================\n// PATIENT\n// ============================================================\n\nmodel PatientProfile {\n  id     String @id @default(cuid())\n  userId String @unique\n\n  dateOfBirth DateTime?\n  gender      String?\n  address     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  appointments Appointment[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ============================================================\n// DOCTOR\n// ============================================================\n\nmodel DoctorProfile {\n  id     String @id @default(cuid())\n  userId String @unique\n\n  specialization String\n  licenseNumber  String? @unique\n  bio            String?\n\n  slotDurationMinutes Int @default(30)\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  workingHours WorkingHour[]\n  leaveDays    LeaveDay[]\n  appointments Appointment[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([specialization])\n}\n\n// ============================================================\n// DOCTOR WORKING HOURS\n// ============================================================\n\nenum DayOfWeek {\n  MONDAY\n  TUESDAY\n  WEDNESDAY\n  THURSDAY\n  FRIDAY\n  SATURDAY\n  SUNDAY\n}\n\nmodel WorkingHour {\n  id       String    @id @default(cuid())\n  doctorId String\n  day      DayOfWeek\n\n  startTime String\n  endTime   String\n\n  doctor DoctorProfile @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([doctorId, day])\n}\n\n// ============================================================\n// DOCTOR LEAVE\n// ============================================================\n\nmodel LeaveDay {\n  id       String   @id @default(cuid())\n  doctorId String\n  date     DateTime\n  reason   String?\n\n  doctor DoctorProfile @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([doctorId, date])\n  @@index([date])\n}\n\n// ============================================================\n// APPOINTMENTS\n// ============================================================\n\nenum AppointmentStatus {\n  HELD\n  CONFIRMED\n  COMPLETED\n  CANCELLED\n  EXPIRED\n  RESCHEDULED\n}\n\nmodel Appointment {\n  id        String @id @default(cuid())\n  patientId String\n  doctorId  String\n\n  startTime DateTime\n  endTime   DateTime\n\n  status AppointmentStatus @default(HELD)\n\n  // Temporary reservation for preventing two users\n  // from simultaneously taking the same slot.\n  holdExpiresAt DateTime?\n\n  // Patient's original symptom submission\n  symptoms String?\n\n  // AI-generated information for doctor\n  preVisitSummary String?\n  urgencyLevel    String?\n\n  patient PatientProfile @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  doctor  DoctorProfile  @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n\n  visit Visit?\n\n  notifications  Notification[]\n  calendarEvents CalendarEvent[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Critical double-booking protection.\n  //\n  // A doctor cannot have two appointments beginning\n  // at the exact same time.\n\n  @@index([patientId])\n  @@index([doctorId])\n  @@index([startTime])\n  @@index([status])\n}\n\n// ============================================================\n// VISIT / CONSULTATION\n// ============================================================\n\nmodel Visit {\n  id            String @id @default(cuid())\n  appointmentId String @unique\n\n  clinicalNotes String\n  diagnosis     String?\n\n  // AI-generated patient-friendly explanation\n  patientSummary String?\n\n  followUpInstructions String?\n\n  appointment Appointment @relation(fields: [appointmentId], references: [id], onDelete: Cascade)\n\n  prescriptions Prescription[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ============================================================\n// PRESCRIPTION\n// ============================================================\n\nmodel Prescription {\n  id      String @id @default(cuid())\n  visitId String\n\n  medicationName String\n  dosage         String\n  frequency      String\n  duration       String?\n\n  instructions String?\n\n  visit Visit @relation(fields: [visitId], references: [id], onDelete: Cascade)\n\n  medications Medication[]\n\n  createdAt DateTime @default(now())\n}\n\n// ============================================================\n// MEDICATION REMINDERS\n// ============================================================\n\nenum ReminderStatus {\n  ACTIVE\n  PAUSED\n  COMPLETED\n}\n\nmodel Medication {\n  id             String @id @default(cuid())\n  prescriptionId String\n\n  reminderStatus ReminderStatus @default(ACTIVE)\n\n  nextReminderAt DateTime?\n\n  prescription Prescription @relation(fields: [prescriptionId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([nextReminderAt])\n  @@index([reminderStatus])\n}\n\n// ============================================================\n// NOTIFICATIONS\n// ============================================================\n\nenum NotificationType {\n  BOOKING_CONFIRMATION\n  APPOINTMENT_REMINDER\n  CANCELLATION\n  LEAVE_NOTIFICATION\n  MEDICATION_REMINDER\n}\n\nenum NotificationChannel {\n  EMAIL\n}\n\nenum NotificationStatus {\n  PENDING\n  SENT\n  FAILED\n}\n\nmodel Notification {\n  id String @id @default(cuid())\n\n  userId String\n\n  appointmentId String?\n\n  type    NotificationType\n  channel NotificationChannel @default(EMAIL)\n  status  NotificationStatus  @default(PENDING)\n\n  recipient String\n  subject   String\n  content   String\n\n  attempts    Int       @default(0)\n  nextRetryAt DateTime?\n\n  sentAt DateTime?\n  error  String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  appointment Appointment? @relation(fields: [appointmentId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status, nextRetryAt])\n  @@index([appointmentId])\n}\n\n// ============================================================\n// GOOGLE CALENDAR\n// ============================================================\n\nenum CalendarEventStatus {\n  ACTIVE\n  CANCELLED\n  FAILED\n}\n\nmodel CalendarEvent {\n  id String @id @default(cuid())\n\n  appointmentId String\n\n  // Google Calendar event ID\n  googleEventId String?\n\n  calendarEmail String\n\n  status CalendarEventStatus @default(ACTIVE)\n\n  lastSyncedAt DateTime?\n  error        String?\n\n  appointment Appointment @relation(fields: [appointmentId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([appointmentId])\n  @@index([googleEventId])\n}\n",
